#!/usr/bin/env python3
# @file gen_crc_tables.py
# @brief Generate utils/src/fu_crc_tab.c (`make tables`)
#
# Copyright (c) 2026 Antony Kasera
# SPDX-License-Identifier: MIT

import sys

HEADER = """/**
 * @file fu_crc_tab.c
 * @brief CRC tables for fu_crc.c
 *
 * Generated by tools/gen/gen_crc_tables.py (`make tables`); do not edit.
 *
 * Copyright (c) 2026 Antony Kasera
 * SPDX-License-Identifier: MIT
 */

#include "fu_crc_tab.h"
"""


def step(crc, width, poly, refl, nbits):
    """Shift nbits zero bits through crc, MSB first or (refl) LSB first."""
    top = 1 << (width - 1)
    mask = (1 << width) - 1
    for _ in range(nbits):
        if refl:
            crc = (crc >> 1) ^ poly if crc & 1 else crc >> 1
        else:
            crc = ((crc << 1) ^ poly) & mask if crc & top else (crc << 1) & mask
    return crc


def byte_table(width, poly, refl):
    shift = 0 if refl else width - 8
    return [step(i << shift, width, poly, refl, 8) for i in range(256)]


def nibble_table(width, poly, refl):
    shift = 0 if refl else width - 4
    return [step(i << shift, width, poly, refl, 4) for i in range(16)]


def slice_tables(t0, n):
    tabs = [t0]
    for _ in range(n - 1):
        prev = tabs[-1]
        tabs.append([(prev[i] >> 8) ^ t0[prev[i] & 0xFF] for i in range(256)])
    return tabs


def emit(name, ctype, digits, values, dims=""):
    per_line = {2: 10, 4: 8, 8: 5}[digits]
    align = " FX_ALIGN_LINE" if len(values) * digits // 2 >= 64 else ""
    out = [f"const {ctype} {name}{dims}{align} = {{"]
    for i in range(0, len(values), per_line):
        chunk = ", ".join(f"0x{v:0{digits}X}U" for v in values[i:i + per_line])
        out.append(f"    {chunk},")
    out.append("};\n")
    return "\n".join(out)


def emit_2d(name, ctype, digits, tabs):
    per_line = {2: 10, 4: 8, 8: 5}[digits]
    out = [f"const {ctype} {name}[{len(tabs)}][256] FX_ALIGN_LINE = {{"]
    for t in tabs:
        out.append("    {")
        for i in range(0, 256, per_line):
            chunk = ", ".join(f"0x{v:0{digits}X}U" for v in t[i:i + per_line])
            out.append(f"        {chunk},")
        out.append("    },")
    out.append("};\n")
    return "\n".join(out)


def main():
    crcs = [
        # name, C type, hex digits, width, poly (reflected if refl), refl
        ("crc8_smbus", "uint8_t", 2, 8, 0x07, False),
        ("crc8_maxim", "uint8_t", 2, 8, 0x8C, True),
        ("crc16_ccitt", "uint16_t", 4, 16, 0x1021, False),
        ("crc16_modbus", "uint16_t", 4, 16, 0xA001, True),
    ]
    parts = [HEADER]
    for name, ctype, digits, width, poly, refl in crcs:
        parts.append(emit(f"fu_{name}_tab", ctype, digits,
                          byte_table(width, poly, refl), "[256]"))
        parts.append(emit(f"fu_{name}_nib", ctype, digits,
                          nibble_table(width, poly, refl), "[16]"))
    t32 = byte_table(32, 0xEDB88320, True)
    parts.append(emit_2d("fu_crc32_tab", "uint32_t", 8, slice_tables(t32, 4)))
    parts.append(emit("fu_crc32_nib", "uint32_t", 8,
                      nibble_table(32, 0xEDB88320, True), "[16]"))
    sys.stdout.write("\n".join(parts))


if __name__ == "__main__":
    main()
